package com.yeyamo_mobile.api.booking_service.infrastructure.persistence;import java.time.Instant;import java.util.UUID;import com.yeyamo_mobile.api.booking_service.domain.SagaStatus;import jakarta.persistence.*;
@Entity@Table(name="booking_payment_sagas")public class PaymentSagaEntity{@Id private UUID id;@OneToOne(fetch=FetchType.EAGER,optional=false)@JoinColumn(name="booking_id",unique=true)private BookingEntity booking;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private SagaStatus status;@Column(name="payment_id",length=120)private String paymentId;@Column(name="failure_reason",length=1000)private String failureReason;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;
 public static PaymentSagaEntity authorization(BookingEntity booking){var e=new PaymentSagaEntity();e.id=UUID.randomUUID();e.booking=booking;e.status=SagaStatus.AUTHORIZATION_REQUESTED;e.createdAt=Instant.now();e.updatedAt=e.createdAt;return e;}public void cancellationRequested(){status=SagaStatus.CANCELLATION_REQUESTED;updatedAt=Instant.now();}public void authorized(String payment){status=SagaStatus.AUTHORIZED;paymentId=payment;failureReason=null;updatedAt=Instant.now();}public void failed(String reason){status=SagaStatus.FAILED;failureReason=reason;updatedAt=Instant.now();}public void refundRequested(){status=SagaStatus.REFUND_REQUESTED;updatedAt=Instant.now();}public void refunded(){status=SagaStatus.REFUNDED;updatedAt=Instant.now();}
 public UUID getId(){return id;}public BookingEntity getBooking(){return booking;}public SagaStatus getStatus(){return status;}public String getPaymentId(){return paymentId;}public String getFailureReason(){return failureReason;}
}
